## Why This Is Asked
This question tests your ability to design per-tenant, real-time UI systems with correct subscription lifecycles andization.

## Key Concepts
 performance optimization through memo- useSyncExternalStore with per-tenant data streams
- memoized selectors with stable identity keys
- React.memo for row component optimization
- conditional rendering with FeatureGate wrapper
- proper cleanup on tenant switch

## Code Example
```javascript
// Store wrapper - creates per-tenant subscription
function createTenantFlagStore(tenantId) {
  let flags = {};
  const subscribers = new Set();

  return {
    getSnapshot: () => flags,
    getServerSnapshot: () => ({}),
    subscribe: (callback) => {
      subscribers.add(callback);
      return () => subscribers.delete(callback);
    },
    updateFlag: (featureName, value) => {
      flags = { ...flags, [featureName]: value };
      subscribers.forEach(cb => cb(flags));
    }
  };
}

// Memoized selector keyed by tenantId and featureName
const featureSelectorCache = new Map();
function selectFeature(tenantId, featureName, tenantStore) {
  const key = `${tenantId}:${featureName}`;
  if (!featureSelectorCache.has(key)) {
    featureSelectorCache.set(key, createSelector(tenantStore, flags => ({
      enabled: flags[featureName]?.enabled ?? false,
      loading: flags[featureName]?.loading ?? true,
      visible: flags[featureName]?.visible ?? true
    })));
  }
  return featureSelectorCache.get(key)(useSyncExternalStore(
    tenantStore.subscribe,
    tenantStore.getSnapshot,
    tenantStore.getServerSnapshot
  ));
}

// Memoized FeatureRow
const FeatureRow = React.memo(function FeatureRow({ featureName, tenantId, store }) {
  const feature = selectFeature(tenantId, featureName, store);
  return (
    <div className="feature-row">
      {feature.loading ? <Spinner /> : 
       feature.enabled ? <FeatureContent name={featureName} /> : 
       <FeatureDisabled />}
    </div>
  );
}, (prevProps, nextProps) => {
  return prevProps.tenantId === nextProps.tenantId && 
         prevProps.featureName === nextProps.featureName;
});

// FeatureGate wrapper
function FeatureGate({ tenantId, featureName, children, fallback = null }) {
  const store = useTenantStore(tenantId);
  const feature = selectFeature(tenantId, featureName, store);

  return feature.enabled ? children : fallback;
}

// Panel integration with cleanup
function FeatureDashboard({ tenantId }) {
  const [currentTenant, setCurrentTenant] = useState(tenantId);

  useEffect(() => {
    if (currentTenant !== tenantId) {
      setCurrentTenant(tenantId);
    }
  }, [tenantId]);

  return (
    <FeatureGate tenantId={tenantId} featureName="dashboard_v2">
      <FeatureRow 
        tenantId={tenantId} 
        featureName="realtime_metrics"
        store={useTenantStore(tenantId)}
      />
    </FeatureGate>
  );
}
```

## Key Takeaways
The solution demonstrates proper separation of concerns: the store handles subscription management, selectors compute derived state efficiently, and components use React.memo to avoid unnecessary re-renders. The FeatureGate provides declarative access control, and cleanup on tenant switch is handled by useEffect's cleanup function in the store subscription.

